import { createEntryPayload } from "./page";

export const EntriesPage = () => {
  const payload = createEntryPayload({
    entryId: "entry-1",
    name: "Draft",
    tags: ["new"],
    enabled: true,
  });

  return <pre>{JSON.stringify(payload)}</pre>;
};

/**
 * @summary entry 생성 payload 원본 입력 계약
 */
interface CreateEntryPayloadInput {
  /**
   * @field 생성 대상 entry 식별자
   */
  entryId: string;
  /**
   * @field 정규화 전 entry 이름
   */
  name: string;
  /**
   * @field entry 분류 태그 목록
   */
  tags: string[];
  /**
   * @field entry 활성화 여부
   */
  enabled: boolean;
}

/**
 * @summary 정규화된 entry 생성 payload 계약
 */
interface CreateEntryPayload {
  /**
   * @field 생성 대상 entry 식별자
   */
  entryId: string;
  /**
   * @field 공백을 정리한 entry 이름
   */
  name: string;
  /**
   * @field entry 분류 태그 목록
   */
  tags: string[];
  /**
   * @field entry 활성화 여부
   */
  enabled: boolean;
}

/**
 * @helper entry 생성 입력을 저장 payload로 정규화
 */
export const createEntryPayload = (
  input: CreateEntryPayloadInput,
): CreateEntryPayload => {
  const { entryId, name, tags, enabled } = input;

  return {
    entryId,
    name: name.trim(),
    tags,
    enabled,
  };
};
